// FSRS-6 spaced-repetition scheduler with the published default weights.
// Mirrors py-fsrs (Scheduler with no learning or relearning steps) at whole-day
// granularity: a same-day re-ask uses the short-term stability formula.
// tests/fsrs.test.mjs checks it against reference values generated by py-fsrs.

export const DEFAULT_W = Object.freeze([
  0.212, 1.2931, 2.3065, 8.2956, 6.4133, 0.8334, 3.0194, 0.001, 1.8722, 0.1666, 0.796,
  1.4835, 0.0614, 0.2629, 1.6483, 0.6014, 1.8729, 0.5425, 0.0912, 0.0658, 0.1542,
]);

export const Rating = Object.freeze({ Again: 1, Hard: 2, Good: 3, Easy: 4 });

const S_MIN = 0.001;
const D_MIN = 1;
const D_MAX = 10;

const FUZZ_RANGES = [
  { start: 2.5, end: 7, factor: 0.15 },
  { start: 7, end: 20, factor: 0.1 },
  { start: 20, end: Infinity, factor: 0.05 },
];

const clampD = (d) => Math.min(Math.max(d, D_MIN), D_MAX);
const clampS = (s) => Math.max(s, S_MIN);

export function createFSRS({ w = DEFAULT_W, retention = 0.9, maxInterval = 36500, fuzz = true } = {}) {
  const DECAY = -w[20];
  const FACTOR = 0.9 ** (1 / DECAY) - 1;

  const initS = (g) => clampS(w[g - 1]);
  const initD = (g, clamp = true) => {
    const d = w[4] - Math.exp(w[5] * (g - 1)) + 1;
    return clamp ? clampD(d) : d;
  };

  function retrievability(s, elapsedDays) {
    return (1 + (FACTOR * Math.max(0, elapsedDays)) / s) ** DECAY;
  }

  function nextInterval(s, r = retention) {
    const ivl = (s / FACTOR) * (r ** (1 / DECAY) - 1);
    return Math.min(Math.max(Math.round(ivl), 1), maxInterval);
  }

  function nextD(d, g) {
    const delta = -(w[6] * (g - 3));
    const damped = d + ((10 - d) * delta) / 9;
    return clampD(w[7] * initD(Rating.Easy, false) + (1 - w[7]) * damped);
  }

  function shortTermS(s, g) {
    let inc = Math.exp(w[17] * (g - 3 + w[18])) * s ** -w[19];
    if (g >= Rating.Hard) inc = Math.max(inc, 1);
    return clampS(s * inc);
  }

  function recallS(d, s, r, g) {
    const hard = g === Rating.Hard ? w[15] : 1;
    const easy = g === Rating.Easy ? w[16] : 1;
    return s * (1 + Math.exp(w[8]) * (11 - d) * s ** -w[9] * (Math.exp((1 - r) * w[10]) - 1) * hard * easy);
  }

  function forgetS(d, s, r) {
    const long = w[11] * d ** -w[12] * ((s + 1) ** w[13] - 1) * Math.exp((1 - r) * w[14]);
    const short = s / Math.exp(w[17] * w[18]);
    return Math.min(long, short);
  }

  function fuzzInterval(ivl, rng) {
    if (ivl < 2.5) return ivl;
    let delta = 1;
    for (const f of FUZZ_RANGES) delta += f.factor * Math.max(Math.min(ivl, f.end) - f.start, 0);
    let lo = Math.max(2, Math.round(ivl - delta));
    const hi = Math.min(Math.round(ivl + delta), maxInterval);
    lo = Math.min(lo, hi);
    return Math.min(Math.round(rng.next() * (hi - lo + 1) + lo), maxInterval);
  }

  /**
   * Review a card. `card` may be undefined/new. `today` is a day number.
   * Returns a new card object; never mutates.
   * opts.retention overrides the scheduler's desired retention (per subject).
   */
  function review(card, g, today, { rng = null, retention: r = retention } = {}) {
    const c = card ? { ...card } : newCard();
    const elapsed = c.lastDay == null ? null : today - c.lastDay;
    if (c.state === 'new' || c.s == null) {
      c.s = initS(g);
      c.d = initD(g);
    } else if (elapsed < 1) {
      c.s = shortTermS(c.s, g);
      c.d = nextD(c.d, g);
    } else {
      const R = retrievability(c.s, elapsed);
      c.s = clampS(g === Rating.Again ? forgetS(c.d, c.s, R) : recallS(c.d, c.s, R, g));
      c.d = nextD(c.d, g);
    }
    if (g === Rating.Again && c.state !== 'new') c.lapses = (c.lapses || 0) + 1;
    c.state = 'review';
    let ivl = nextInterval(c.s, r);
    if (fuzz && rng) ivl = fuzzInterval(ivl, rng);
    c.ivl = ivl;
    c.due = today + ivl;
    c.lastDay = today;
    c.reps = (c.reps || 0) + 1;
    return c;
  }

  return { review, retrievability, nextInterval, fuzzInterval, initS, initD, DECAY, FACTOR };
}

export function newCard() {
  return { state: 'new', s: null, d: null, lastDay: null, due: null, ivl: 0, reps: 0, lapses: 0 };
}
